pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz the recipient address and amount; these are general inputs
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient wide-range but non-zero to be realistic; still allow zero as admissible
        // ensure amount can be any uint (no tight constraints)
        // record before
        uint256 before = c.proposalCount();
        // perform the call as a regular EOA
        bool ok;
        try c.newGrantProposal(recipient, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // After a successful public call, the reference contract guarantees proposalCount increased by 1.
        // We assert that if the call did not revert, proposalCount == before + 1.
        // This is the single assertion reading c's public getter.
        if (ok) {
            assertTrue(c.proposalCount() == before + 1);
        } else {
            // If the call reverted, still assert that proposalCount did not change (revert implies no state change)
            assertTrue(c.proposalCount() == before);
        }
    }
}

