pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: recipient address and amount
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient wide but not zero to allow checking stored mapping for non-zero address
        // allow zero too (wide domain). No tight bounds so mutant-triggering inputs remain admissible.

        // record before
        uint256 before = c.proposalCount();

        // call newGrantProposal as the caller
        // use vm.prank to vary msg.sender implicitly via fuzzed recipient doesn't affect caller so keep default
        // perform the call
        c.newGrantProposal(recipient, amount);

        // after
        uint256 after = c.proposalCount();

        // The reference contract guarantees proposalCount increments by exactly 1 and the grant stored
        // at index `before` equals the provided recipient and amount. We can only read via the public
        // auto-generated getter for mapPID_grant (struct) — but mapPID_grant is public so solidity provides
        // a getter that returns (address,uint256).
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(before);

        // Single assertion: both the count increment and stored grant match the rule
        assertTrue(after == before + 1 && storedRecipient == recipient && storedAmount == amount);
    }
}

