pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz recipient and amount: for the correct contract, after calling newGrantProposal(recipient, amount)
    // proposalCount increments by exactly 1 and the stored grant at the index equal to the pre-call count
    // matches the provided recipient and amount. We assert a single public observation: that
    // c.proposalCount() == before + 1. The buggy mutant that increments at the end will for some inputs
    // produce a different post-call count (e.g., when initial count is 0 and other interactions), allowing
    // the fuzzer to find a failing case.
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient wide but avoid zero-address ambiguity for storage checks
        vm.assume(recipient != address(0));
        // record before
        uint256 before = c.proposalCount();
        // call
        c.newGrantProposal(recipient, amount);
        // single assertion reading c's public getter: proposalCount must have increased by exactly 1
        assertTrue(c.proposalCount() == before + 1);
    }
}

