    function setUp() public { c = new C(); }

    // Fuzz recipient and amount: the behavior difference manifests purely in proposalCount increment
    function testFuzz_property(address recipient, uint256 amount) public {
        // Keep recipient as any address (including zero) and amount any uint; wide domain, no assumes
